# ─────────────────────────────────────────────────────────────────────────
# The one cap the cards actually differ on, so far.
#
# Faith Muthinja's Ultimate RM card scores VIC Premiums at exactly 200.0%:
# 450,523 against a YTD target of 206,219.30 is 218.5%, and the card prints
# 200.0% with a weighted score of 10.0% on a 5.0% weight. The cell holds 2
# exactly, which is a cap and not a coincidence.
#
# Abed Lelgo's Commercial RM card caps the same measure at 120% - VIC
# Premiums, 15,293,137.18 against 362,165.61, printed as 1.2. So this is a
# property of the ROLE's card, not of the measure, and it belongs on the
# mapping rather than on the KPI or the source.
#
# Only this one line is set. The other roles are left on the usual 120%
# because no card has been seen that says otherwise, and guessing a cap
# would quietly change what people are paid on.
CAPS = {
    ("ultimate_rm", "personal_banking_vic_premiums"): 2.0,
}


def set_the_caps(apps, schema_editor):
    Mapping = apps.get_model("staff_management", "ScRoleKpiMapping")

    done = []
    for (role, kpi), cap in CAPS.items():
        changed = Mapping.objects.filter(
            role_code=role, kpi_code=kpi).update(score_cap=cap)
        if changed:
            done.append(f"{role}/{kpi} -> {cap:.0%}")

    if done:
        print(f"  Score caps: {len(done)} line(s) now cap above the usual "
              f"120% - {', '.join(done)}")
    else:
        print("  Score caps: no mapping matched; the seed may have changed.")


def clear_the_caps(apps, schema_editor):
    Mapping = apps.get_model("staff_management", "ScRoleKpiMapping")
    for role, kpi in CAPS:
        Mapping.objects.filter(role_code=role, kpi_code=kpi).update(
            score_cap=None)
    print("  Score caps: cleared.")


Migration.operations.append(
    migrations.RunPython(set_the_caps, clear_the_caps))
